import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';
import {hash,json,read,filesIn,viewer,docs,write,course} from './model.ts';
import {captureOwnedFileFallback} from './owned-file-browser-fallback.ts';
const self=fileURLToPath(import.meta.url),sha=(f:string)=>hash(fs.readFileSync(f)),ref=(f:string)=>({path:path.resolve(f),sha256:sha(f)});
export function callbackFixtureClosure(id:string){
 const step=course().steps.find(s=>s.id===id);assert(step?.browser_check);const seen=new Set<string>(),sources:any[]=[],required=new Set<string>();
 const visit=(file:string)=>{file=path.resolve(file);assert(file.startsWith(path.join(docs,'journey/checks/browser')+path.sep));if(seen.has(file))return;seen.add(file);const text=read(file);sources.push(ref(file));for(const m of text.matchAll(/assets\/pb\/[a-z0-9-]+\.pb/g))required.add(m[0]);for(const m of text.matchAll(/require\(['"](\.\/[^'"]+)['"]\)/g)){const child=path.resolve(path.dirname(file),m[1]);if(child.endsWith('.cjs'))visit(child);}};
 visit(path.join(docs,step.browser_check));return{sources,requiredPbAssets:[...required].sort(),scope:'Transitive literal relative CJS requires and every literal assets/pb filename in their source. Generated in-memory/base64 fixtures and checkpoint sample.pb keep their unchanged original executors; no synthetic replacement.'};
}
export function prepareFixtureQualifiedFallback(id:string,builtFile:string){
 builtFile=path.resolve(builtFile);const p=json(builtFile);assert.equal(p.id,id);assert.equal(p.status,'BUILT_NOT_CAPTURED');const closure=callbackFixtureClosure(id),registryFile=path.join(viewer,'assets/pb/course-fixtures.json'),registry=json(registryFile);
 for(const name of closure.requiredPbAssets){assert(name in p.source.assets,'Required fixture must be declared in actual retained source bindings: '+name);const row=registry.files.find((r:any)=>'assets/pb/'+r.file===name);assert(row,'Frozen fixture registry entry required');assert.equal(sha(path.join(viewer,name)),row.sha256);assert.equal(p.source.assets[name],row.sha256);}
 const identity={helper:ref(self),actualBuild:ref(builtFile),source:p.source,closure,fixtureRegistry:ref(registryFile)},folder=path.join(viewer,'target/course-presentation/fixture-qualified-fallback',id+'-'+hash(JSON.stringify(identity)).slice(0,20)),preparedFile=path.join(folder,'prepared.json');
 if(fs.existsSync(preparedFile)){const prior=json(preparedFile);assert.deepEqual(prior.fixtureQualification.identity,identity);for(const r of prior.fixtureQualification.assets)assert.equal(sha(r.destination),r.sha256);return prior;}
 assert(!fs.existsSync(folder),'Preserve incomplete fixture preparation');fs.mkdirSync(folder,{recursive:true});const workspace=path.join(viewer,'target/course-presentation/incremental-browser-builds/cases',id+'-fixture-runtime-'+hash(JSON.stringify(identity)).slice(0,20),'workspace');assert(!fs.existsSync(path.dirname(workspace)));fs.cpSync(p.workspace,workspace,{recursive:true});const copiedFiles=filesIn(p.workspace).map(f=>{const relative=path.relative(p.workspace,f),target=path.join(workspace,relative),digest=sha(f);assert.equal(sha(target),digest);return{relative,sha256:digest};});
 const assets=Object.entries(p.source.assets).map(([name,digest])=>{assert(name.startsWith('assets/'));const source=path.join(p.native,name),live=path.join(viewer,name),destination=path.join(workspace,name);assert.equal(sha(source),digest);assert.equal(sha(live),digest);fs.mkdirSync(path.dirname(destination),{recursive:true});if(fs.existsSync(destination))assert.equal(sha(destination),digest);else fs.copyFileSync(source,destination,fs.constants.COPYFILE_EXCL);assert.equal(sha(destination),digest);return{name,source:ref(source),live:ref(live),destination,sha256:digest};});
 const qualification={status:'PREPARED_EXACT_DECLARED_ASSETS_IN_FRESH_RUNTIME_CLONE_NO_COMPILER_EXECUTION',identity,originalFailedWorkspaceUntouched:p.workspace,copiedFiles,assets,compiledArtifactReused:p.imageBuild,scope:'Only a fresh runtime filesystem clone and exact already-declared source assets at original relative paths. Original source/native/dist/build receipts, failed workspace and canonical assertions unchanged. No renderer rebuild and no fabricated historical PB identity.'};
 const receipt=path.join(folder,'fixture-materialization.json');write(receipt,JSON.stringify(qualification,null,2)+'\n');const facade={...p,folder,preparedFile,workspace,dist:path.join(workspace,'target/course-checks',id,'dist'),pins:{...p.pins,[self]:sha(self),[builtFile]:sha(builtFile),[receipt]:sha(receipt),...Object.fromEntries(assets.map(r=>[r.destination,r.sha256]))},originalActualBuild:ref(builtFile),fixtureQualification:qualification,fixtureQualificationReceipt:ref(receipt)};write(preparedFile,JSON.stringify(facade,null,2)+'\n');return facade;
}
export async function captureFixtureQualifiedFallback(id:string,builtFile:string){const prepared=prepareFixtureQualifiedFallback(id,builtFile),r=await captureOwnedFileFallback(id,prepared.preparedFile),record={...r,runtimeFixtureQualification:prepared.fixtureQualificationReceipt,actualRetainedCompilerBuild:prepared.originalActualBuild,scope:r.scope+' Exact already-declared PB/text assets materialized in a fresh runtime clone; original missing-file failure workspace remains untouched.'},file=path.join(prepared.folder,'capture.json');assert(!fs.existsSync(file));fs.writeFileSync(file,JSON.stringify(record,null,2)+'\n',{flag:'wx'});return{...record,record:file};}
if(process.argv[1]&&path.resolve(process.argv[1])===self){const[mode,id,built]=process.argv.slice(2);const r=mode==='audit'?callbackFixtureClosure(id):mode==='prepare'?prepareFixtureQualifiedFallback(id,built):mode==='capture'?await captureFixtureQualifiedFallback(id,built):null;assert(r);console.log(JSON.stringify(r,null,2));}

